23		bundler: string;
24		runtime: string;
25		equal: boolean;
26		first: BuildProfileLane;
27		second: BuildProfileLane;
28	}>;
29	export type PapercupsBuildProfile = Readonly<{
30		schemaVersion: string;
31		result: string;
32		fixture: string;
33		builds: Readonly<{ baseline: BuildProfileBuild; target: BuildProfileBuild }>;
34		parity: Readonly<{ behavioral: string; journeys: string; runtimeEquivalence: string }>;
35		gates: Readonly<Record<string, string>>;
36		integrity: Readonly<{ algorithm: string; canonicalDigest: string }>;
37	}>;
38	
39	export type PapercupsBuildProfileVerification = Readonly<{
40		result: 'pass';
41		fixture: string;
42		baselineDeterministic: boolean;
43		targetDeterministic: boolean;
44		baselineFiles: number;
45		targetFiles: number;
