50	/**
51	 * The application identity must never leak into the reusable React product
52	 * surface. Anything that names this application there is a scope violation,
53	 * so the fixture asserts its own absence.
54	 */
55	export async function applicationNamedProductSymbols(
56		needle: string,
57	): Promise<readonly string[]> {
58		const lowered = needle.toLowerCase();
59		const offenders: string[] = [];
60		for (const entry of await readdir(reactAdapterRoot, { withFileTypes: true })) {
61			if (!entry.isFile()) continue;
62			const source = await readFile(path.join(reactAdapterRoot, entry.name), 'utf8');
63			if (source.toLowerCase().includes(lowered)) offenders.push(entry.name);
64		}
65		return offenders.sort();
66	}
67	
68	export async function readPapercupsBuildProfile(): Promise<PapercupsBuildProfile> {
69		const body = await readFile(path.join(evidenceRoot, 'build-profile.json'), 'utf8');
70		const profile = JSON.parse(body) as PapercupsBuildProfile;
71		const { integrity, ...unsigned } = profile;
72		if (sha256(canonicalize(unsigned)) !== integrity.canonicalDigest)
73			throw new Error('Papercups build profile canonical digest differs');
74		return profile;
75	}
