77	export async function verifyPapercupsBuildProfile(): Promise<PapercupsBuildProfileVerification> {
78		const profile = await readPapercupsBuildProfile();
79		const { baseline, target } = profile.builds;
80		if (!baseline.equal || baseline.first.digest !== baseline.second.digest)
81			throw new Error('Papercups baseline builds are not deterministic');
82		if (!target.equal || target.first.digest !== target.second.digest)
83			throw new Error('Papercups target builds are not deterministic');
84		if (profile.parity.behavioral !== 'not-tested' || profile.parity.journeys !== 'not-tested')
